import { timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Column helpers shared by every table. Column names come from the TS property names,
 * converted to snake_case (`casing: "snake_case"` in the client and drizzle.config).
 */

/** Random UUID primary key, generated by PostgreSQL. */
export const primaryId = () => uuid().primaryKey().defaultRandom();

/** Timestamp with time zone; always stored as UTC. */
export const timestampTz = () => timestamp({ withTimezone: true, mode: "date" });

export const timestamps = {
  createdAt: timestampTz().notNull().defaultNow(),
  updatedAt: timestampTz()
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};
